def _embed_criticalPoints_partial_cache(parent_data, partial_cache):
    partial_cache.points = parent_data.points
    return partial_cache

class EmbedScalarCriticalPoints(Node):

    def __init__(self, parent_node_id : str, radius : float = 3.0, color_scheme : List[str] = ["#3b4cc0", "#aac7fd", "#f7b89c", "#b40426", "#000000"]):
        if correctness_checks_on():
            if len(color_scheme) != 5:
                raise Exception("color_scheme list should have five elements")

            for elt in color_scheme:
                if not is_hex_string(elt):
                    raise Exception(f"Element {elt} in color_scheme is not a hex string")

            del elt

        super().__init__(parent_node_id, types.ScalarCriticalPoints, types.ScalarCriticalPointsEmbedding, locals(), False, True)

        self.radius = radius
        self.color_scheme = color_scheme

    def compatible_to_visualize(self, other):
        if issubclass(other.node_type, types.TrackedScalarCriticalPointsEmbedding) and \
           self.parent_node_id == other.parent_node.parent_node_id:

            return False, "Cannot visualize a scalar field's set of critical points both tracked and untracked at the same time. "\
                          "They will overlap."

        return True, ""

    @classmethod
    def chat_description(cls):
        return "queued embedding scalar field critical points"

    @classmethod
    def description(cls):
        return 'Create a geometric embedding of the critical points of scalar field data.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'A node of type scalar_cp which corresponds to some critical points '
                           'that should be visualized.',
         'radius': 'The radius of the spheres that will be used to visualize the critical '
                   'points.',
         'color_scheme': 'A list of five hex strings that respectively correspond to the colors that '
                   'will be used to visualize minima, index 1 saddles, index 2 saddles, '
                   'maxima, and degenerate critical points.'}

    def _evaluation_logic(self, parent_data, time_step):
        return types.ScalarCriticalPointsEmbedding(parent_data.points, self.radius, "CriticalType", color_list_to_lut(self.color_scheme))

    def _evaluation_logic_partial_cache(self, parent_data, partial_cache, time_step):
        return _embed_criticalPoints_partial_cache(parent_data, partial_cache)

